@pytest.fixture
def client() -> ApiClient:
    return unittest.mock.MagicMock(_name="client")


@pytest.fixture
def provider(client: ApiClient) -> GitLabProvider:
    return GitLabProvider(
        client=client,
        organization_id=1,
        repository=Repository(
            id=1,
            integration_id=1,
            name="test-repo",
            organization_id=1,
            is_active=True,
            external_id="gitlab.com:79787061",
            provider_name="gitlab",
            web_base_url=None,
        ),
    )


class ClientForwardedCall(NamedTuple):
    method: str
    path: str
    json_response: Any
    data: dict | None = None
    params: dict | None = None


class ForwardToClientTest(NamedTuple):
    provider_method: Callable
    provider_args: dict
    client_calls: list[ClientForwardedCall]
    provider_return_value: Any


def _make_mock_response(json_data):
    response = unittest.mock.MagicMock()
    response.json.return_value = json_data
    response.status_code = 200
    response.headers = {}
    return response


