def test_forward_to_client(client, provider: GitLabProvider, param: ForwardToClientTest):
    # Setup client mock to return responses based on call order
    responses = [_make_mock_response(call.json_response) for call in param.client_calls]
    client.request.side_effect = responses

    # Call the provider, check the return value
    assert param.provider_method(provider, **param.provider_args) == param.provider_return_value

    # Check client.request calls
    assert client.request.call_count == len(param.client_calls)
    for client_call, mock_call in zip(param.client_calls, client.request.call_args_list, strict=False):
        assert mock_call.kwargs["method"] == client_call.method
        assert mock_call.kwargs["path"] == client_call.path
        if client_call.params is not None:
            assert mock_call.kwargs["params"] == client_call.params
        if client_call.data is not None:
            assert mock_call.kwargs["data"] == client_call.data


def test_get_pull_request_diff(client, provider: GitLabProvider):
    diff_text = "diff --git a/f.py b/f.py\n@@ -0,0 +1 @@\n+hi\n"
    response = unittest.mock.MagicMock()
    response.text = diff_text
    response.status_code = 200
    response.headers = {}
    client.request.return_value = response

    result = provider.get_pull_request_diff("1")

    assert result == {
        "data": diff_text,
        "type": "gitlab",
        "raw": {"data": diff_text, "headers": None},
        "meta": {},
    }
    assert client.request.call_args.kwargs["method"] == "GET"
    assert client.request.call_args.kwargs["path"] == "/projects/79787061/merge_requests/1/raw_diffs"


def test_get_readme_skips_directory_named_readme(client, provider: GitLabProvider):
    file_response = _make_mock_response(
        {
            "file_name": "README.md",
            "file_path": "README.md",
            "size": 5,
            "encoding": "base64",
            "ref": "main",
            "blob_id": "blobsha",
            "commit_id": "commitsha",
            "last_commit_id": "commitsha",
            "execute_filemode": False,
            "content": "aGVsbG8=",
        }
    )
    tree_response = _make_mock_response(
        [
            {"id": "dir", "name": "readme-assets", "type": "tree", "path": "readme-assets", "mode": "040000"},
            {"id": "blobsha", "name": "README.md", "type": "blob", "path": "README.md", "mode": "100644"},
        ]
    )
    client.request.side_effect = [tree_response, file_response]

    result = provider.get_readme(ref="main")

    assert result["data"]["path"] == "README.md"
    fetched_paths = [call.kwargs["path"] for call in client.request.call_args_list]
    assert fetched_paths == [
        "/projects/79787061/repository/tree",
        "/projects/79787061/repository/files/README.md",
    ]


def test_get_readme_raises_readme_not_found_when_no_readme_in_tree(client, provider: GitLabProvider):
    client.request.return_value = _make_mock_response(
        [
            {"id": "abc", "name": "src", "type": "tree", "path": "src", "mode": "040000"},
            {"id": "def", "name": "LICENSE", "type": "blob", "path": "LICENSE", "mode": "100644"},
        ]
    )

    with pytest.raises(SCMCodedError) as exc_info:
        provider.get_readme(ref="main")

    assert exc_info.value.code == "readme_not_found"


def test_get_pull_request_template_yields_md_files_from_template_dir(client, provider: GitLabProvider):
    tree_response = _make_mock_response(
        [
            {
                "id": "a",
                "name": "feature.md",
                "type": "blob",
                "path": ".gitlab/merge_request_templates/feature.md",
                "mode": "100644",
            },
            {
                "id": "b",
                "name": "bug.md",
                "type": "blob",
                "path": ".gitlab/merge_request_templates/bug.md",
                "mode": "100644",
            },
            {
                "id": "c",
                "name": "notes.txt",
                "type": "blob",
                "path": ".gitlab/merge_request_templates/notes.txt",
                "mode": "100644",
            },
        ]
    )

    def make_file_response(path: str):
        return _make_mock_response(
            {
                "file_name": path.rsplit("/", 1)[-1],
                "file_path": path,
                "size": 5,
                "encoding": "base64",
                "ref": "main",
                "blob_id": "blob",
                "commit_id": "commit",
                "last_commit_id": "commit",
                "execute_filemode": False,
                "content": "aGVsbG8=",
            }
        )

    client.request.side_effect = [
        tree_response,
        make_file_response(".gitlab/merge_request_templates/feature.md"),
        make_file_response(".gitlab/merge_request_templates/bug.md"),
    ]

    results = list(provider.get_pull_request_template(ref="main"))

    assert [r["data"]["path"] for r in results] == [
        ".gitlab/merge_request_templates/feature.md",
        ".gitlab/merge_request_templates/bug.md",
    ]


def test_get_pull_request_template_returns_empty_when_dir_missing(client, provider: GitLabProvider):
    response = unittest.mock.MagicMock()
    response.status_code = 404
    response.content = b'{"message":"404 Tree Not Found"}'
    response.request = unittest.mock.MagicMock(headers={}, body=None)
    client.request.return_value = response

    results = list(provider.get_pull_request_template(ref="main"))

    assert results == []


def test_get_directory_contents_raises_when_path_is_not_directory(client, provider: GitLabProvider):
    response = unittest.mock.MagicMock()
    response.status_code = 404
    response.content = b'{"message":"404 Tree Not Found - path README.md is not treeish"}'
    response.request = unittest.mock.MagicMock(headers={}, body=None)
    client.request.return_value = response

    with pytest.raises(SCMCodedError) as exc_info:
        provider.get_directory_contents(path="README.md", ref="main")

    assert exc_info.value.code == "path_is_not_directory"
    assert exc_info.value.detail == "README.md"


